import sys

data = sys.stdin.read().split()
m = int(data[0])
rides = [(int(data[1 + 3 * i]), int(data[2 + 3 * i]), int(data[3 + 3 * i])) for i in range(m)]
best = 0
for mask in range(1 << m):
    chosen = [rides[i] for i in range(m) if mask >> i & 1]
    ok = True
    for x in range(len(chosen)):
        for y in range(x + 1, len(chosen)):
            a, b = chosen[x], chosen[y]
            if not (a[1] <= b[0] or b[1] <= a[0]):
                ok = False
    if ok:
        best = max(best, sum(e - s + t for s, e, t in chosen))
print(best)

